/* Design-only, offline wireframes. No API, authentication, uploads, or persistence. */
const A = '../../../landing/public/';
const screens = [
 {id:'WF-01',title:'01 · Catálogo de torneios',phase:'Primeira entrega',role:'Visitante',states:{public:'Público',member:'Membro da guilda',empty:'Sem torneios',error:'Falha de carregamento'},rules:['PROD-003','CAT-001','CAT-004','CAT-005'],refs:['tournaments/catalog.md','product.md'],notes:['Eventos internos só aparecem para membros e staff. Não exibir cartões bloqueados ao visitante.','Monomachia é uma configuração do catálogo. O segundo evento é fictício e demonstra reutilização.','Busca, filtros e composição dos cartões são propostas de apresentação.'],render:catalog},
 {id:'WF-02',title:'02 · Detalhes do torneio',phase:'Primeira entrega',role:'Visitante',states:{open:'Inscrições abertas',full:'Lotado, inscrições abertas',closed:'Inscrições encerradas',unknown:'Informações não configuradas'},rules:['CAT-002','CAT-003','CAT-004','CAT-008','CAP-008','MONO-003'],refs:['tournaments/catalog.md','tournaments/events/monomachia-2027.md','tournaments/capacity-and-waitlist.md'],notes:['Lotação e encerramento são estados diferentes. Um evento lotado ainda pode receber inscrições.','Valores de R$ 150,00, 64 vagas e janela de inscrição são uma fixture de design, não fatos de Monomachia.','Regulamento, local, equipamento e horários finais não foram fornecidos.'],render:detail},
 {id:'WF-03',title:'03 · Entrar e criar conta',phase:'Primeira entrega',role:'Visitante',states:{login:'Entrar',signup:'Criar conta',verify:'Verificar e-mail',recover:'Recuperar senha',reset:'Definir nova senha',expired:'Sessão expirada',unavailable:'Serviço indisponível'},rules:['AUTH-001','AUTH-002','AUTH-003','AUTH-006','REG-011'],refs:['identity/authentication-and-access.md','tournaments/registration.md'],notes:['E-mail/senha e Google. A escolha do torneio continua após autenticação.','Callbacks e endereço de recuperação são decisões de implementação.','O protótipo simula navegação; não autentica ninguém e não envia e-mails.'],render:auth},
 {id:'WF-04',title:'04 · Inscrição pessoal',phase:'Primeira entrega',role:'Participante',states:{adult:'Maior de idade',minor:'Menor de idade',full:'Evento lotado',invalid:'Campos inválidos',duplicate:'Inscrição duplicada',closed:'Encerrado durante o preenchimento'},rules:['REG-001','REG-004','REG-005','REG-010','REG-011','REG-015','PRIV-001','PRIV-002','PRIV-005','PRIV-010'],refs:['tournaments/registration.md','tournaments/consent-and-privacy.md'],notes:['Somente a própria pessoa. E-mail exibido é o e-mail da conta; documento não é usado como credencial de acesso.','Formulário único com seções; não propõe salvar rascunho nem inscrição de terceiros.','PRIV-Q1: textos finais de consentimento pendentes. Aqui estão títulos de escolhas, não redação jurídica.','Sem opt-out de lista de participantes. Sem campo de nota interna visível ao participante.'],render:registration},
 {id:'WF-05',title:'05 · Pix e comprovante',phase:'Primeira entrega',role:'Participante',states:{initial:'Aguardando pagamento',replace:'Substituir comprovante',rejected:'Comprovante recusado',fileerror:'Arquivo inválido',late:'Prazo de pagamento passado'},rules:['PAY-001','PAY-003','PAY-004','PAY-006','PAY-010','PAY-011'],refs:['tournaments/payments-and-confirmation.md','tournaments/registration.md'],notes:['Pix é realizado fora da plataforma; enviar o arquivo não transfere dinheiro nem confirma vaga.','PDF, JPEG e PNG até 10 MB. Participante vê somente a versão mais recente.','A chave é propositalmente fictícia/não utilizável. O seletor de arquivo não lê nem envia o conteúdo.'],render:payment},
 {id:'WF-06',title:'06 · Situação da inscrição',phase:'Primeira entrega',role:'Participante',states:{review:'Pagamento em análise',confirmed:'Inscrição confirmada',waitlist:'Pagamento aprovado, em espera'},rules:['REG-006','REG-007','CAP-002','CAP-005','CAP-007','PAY-011'],refs:['tournaments/registration.md','tournaments/capacity-and-waitlist.md','tournaments/payments-and-confirmation.md'],notes:['Sem posição na fila, previsão de chamada ou promoção automática. Staff escolhe quem confirmar.','A tela de espera diz explicitamente que o pagamento está aprovado e a vaga não está confirmada.','Para menor: confirmação não dispensa acompanhamento e conferência presencial de documentos.'],render:status},
 {id:'WF-07',title:'07 · Minhas inscrições',phase:'Primeira entrega',role:'Participante',states:{list:'Com inscrições',empty:'Nenhuma inscrição'},rules:['REG-007','REG-008','REG-004','AUTH-009'],refs:['tournaments/registration.md','identity/authentication-and-access.md'],notes:['Listagem restrita ao proprietário. O número de inscrição não concede acesso a outros registros.','Atalhos de pagamento e acompanhamento dependem do estado da inscrição.'],render:myRegistrations},
 {id:'WF-08',title:'08 · Dados da minha inscrição',phase:'Primeira entrega',role:'Participante',states:{edit:'Editar dados permitidos',conflict:'Correção cria duplicidade'},rules:['REG-008','REG-009','PRIV-005','PRIV-003'],refs:['tournaments/registration.md','tournaments/consent-and-privacy.md'],notes:['Esta tela edita TournamentSignup, não atribui roles ou muda a identidade da conta.','Status, titular, evento, número e timestamps não são editáveis. Nota de segurança não aparece.','Alterações nas declarações preservam o histórico de versões aceitas. PRIV-Q4 não é resolvida com um botão de exclusão.'],render:editRegistration},
 {id:'WF-09',title:'09 · Fila de análise da equipe',phase:'Primeira entrega',role:'Staff (admin)',states:{queue:'Comprovantes pendentes',empty:'Sem pendências'},rules:['ADM-001','ADM-002','ADM-004','AUTH-008','PRIV-004'],refs:['tournaments/administration.md','identity/authentication-and-access.md','tournaments/consent-and-privacy.md'],notes:['Staff tem acesso global, sem atribuição por torneio. Controles continuam limitados pelas regras de domínio.','Não propõe controle genérico para editar status. Exportações ficam fora desta primeira entrega.'],render:staffQueue},
 {id:'WF-10',title:'10 · Revisar pagamento',phase:'Primeira entrega',role:'Staff (admin)',states:{available:'Vaga disponível',full:'Sem vaga disponível',reject:'Solicitar novo comprovante',late:'Pix após o prazo',minor:'Documentação de menor',race:'Vaga ocupada durante análise'},rules:['PAY-004','PAY-005','PAY-011','PAY-013','CAP-003','ADM-005','PRIV-010'],refs:['tournaments/payments-and-confirmation.md','tournaments/administration.md','tournaments/consent-and-privacy.md','tournaments/capacity-and-waitlist.md'],notes:['Aprovar pagamento confere elegibilidade/documentação e capacidade no backend, atomicamente.','Lotação muda o resultado para espera, nunca para overbooking. Arquivo não comprova transferência por si só.','Recusa precisa de motivo e notificação; não cancela a inscrição. Staff vê histórico de evidências.','Ações são simulações locais. Não há dados, documentos ou recibos reais.'],render:staffReview},
 {id:'WF-11',title:'11 · Seleção da lista de espera',phase:'Extensão de torneios',role:'Staff (admin)',states:{seat:'Uma vaga disponível',full:'Sem vaga disponível'},rules:['CAP-003','CAP-005','CAP-009','ADM-006'],refs:['tournaments/capacity-and-waitlist.md','tournaments/administration.md'],notes:['Capacidade inicial já é protegida; esta interface mais ampla de operação é uma extensão.','Não ordenar por prioridade de fila nem criar convites com prazo. A seleção é decisão explícita de staff.','Pagamento já aprovado: a ação é confirmar participação, não cobrar ou aprovar novamente.'],render:waitlist},
 {id:'WF-12',title:'12 · Configuração do torneio',phase:'Extensão de torneios',role:'Staff (admin)',states:{edit:'Editar informações',capacityerror:'Capacidade abaixo dos confirmados'},rules:['CAT-008','CAT-009','CAP-009','ADM-008','ADM-010'],refs:['tournaments/catalog.md','tournaments/administration.md','tournaments/capacity-and-waitlist.md'],notes:['Não adiciona ciclo rascunho/publicado/arquivado ao recurso Tournament.','Mudanças materiais notificam inscritos; regulamentos preservam aceites anteriores.','Capacidade em branco significa ilimitada. Não há override abaixo dos confirmados.'],render:eventSettings},
 {id:'WF-13',title:'13 · Cancelamento e reembolso',phase:'Extensão de torneios',role:'Participante / staff',states:{confirm:'Solicitar cancelamento pago',unpaid:'Cancelamento sem pagamento',pending:'Cancelado, reembolso pendente',refunded:'Reembolso concluído',staff:'Registrar devolução pela equipe'},rules:['REG-013','REG-016','PAY-009','PAY-012','ADM-006','ADM-009'],refs:['tournaments/registration.md','tournaments/payments-and-confirmation.md','tournaments/administration.md'],notes:['Cancelamento libera a vaga imediatamente. Reembolso é uma dimensão separada da participação.','Reembolso exato do valor recebido em até 10 dias úteis. Sem transferência automática.','Sem botão Reabrir. Nova inscrição pode ser criada mesmo com reembolso anterior pendente.'],render:refund},
 {id:'WF-14',title:'14 · Resultados e participantes',phase:'Extensão de torneios',role:'Visitante / membro',states:{unavailable:'Resultados indisponíveis',published:'Área de resultados publicados',directory:'Lista limitada de participantes',restricted:'Evento interno — acesso negado'},rules:['RES-001','RES-003','RES-004','RES-AC-002','PRIV-006'],refs:['tournaments/results.md','tournaments/consent-and-privacy.md'],notes:['RES-Q1–Q4 permanecem abertas: não desenhar placar ao vivo, ranking, chave, importação ou publicação como decisão aprovada.','Área publicada é um contêiner sem formato definido. Diretório usa apenas nome, equipe, cidade/país e confirmação.','Diretório mostrado em contexto autenticado; resultados públicos não expõem registros privados.'],render:results},
 {id:'WF-15',title:'15 · Associação e mensalidades',phase:'Futuro · conceito',role:'Membro da guilda',states:{concept:'Estrutura sem política definida'},rules:['MEM-001','MEM-002','MEM-003','MEM-004','MEM-006'],refs:['membership/overview.md'],notes:['MEM-Q1–Q5 bloqueiam vocabulário de situação, cálculo e cobrança. Não supor mensalidade, inadimplência ou período.','Não há pagar agora, cobrança recorrente ou débito automático. Pagamento de torneio não muda mensalidade.','Exceções e descontos estão reservados como contexto futuro, não regras calculadas.'],render:membership},
 {id:'WF-16',title:'16 · Inventário da guilda',phase:'Futuro · conceito',role:'Staff (admin)',states:{list:'Lista de equipamentos',edit:'Editar registro'},rules:['INV-001','INV-003','INV-004','INV-005','INV-006','INV-007'],refs:['inventory/overview.md'],notes:['Somente admins podem ver e gerenciar. Membros usam fisicamente equipamentos, mas não acessam esta interface.','Apenas equipamento, tipo, quantidade e condição. Sem empréstimos, reservas, localização, manutenção ou patrimônio por unidade.','Retirar do inventário é uma intenção; arquivamento versus exclusão fica para implementação.'],render:inventory}
];
let current = screens[0], state = 'public', currentEvent = 'mono';
const eventTitle = () => currentEvent === 'mono' ? 'Monomachia Karlbrüder 2027' : 'Encontro de esgrima da guilda';
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tag = (text,color='gray') => `<span class="tag ${color}">${text}</span>`;
const button = (text,id,variant='',extra='') => `<button type="button" class="button ${variant}" ${id ? `data-go="${id}"` : ''} ${extra}>${text}</button>`;
const notice = (title,text,kind='') => `<div class="notice ${kind}"><div><strong>${title}</strong>${text}</div></div>`;
const field = (label,value='',opts='') => `<label class="field">${label}<input ${opts} value="${esc(value)}"></label>`;
const textarea = (label,value='') => `<label class="field">${label}<textarea>${esc(value)}</textarea></label>`;
const selectField = (label,options) => `<label class="field">${label}<select>${options.map(v=>`<option>${v}</option>`).join('')}</select></label>`;
const facts = rows => `<dl class="facts">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
const intro = (category,title,sub='',action='') => `<div class="page-intro"><div><p class="overline">${category}</p><h2>${title}</h2>${sub?`<p class="muted no-margin">${sub}</p>`:''}</div>${action}</div>`;
const file = (name='comprovante-exemplo.pdf',details='Último envio · exemplo fictício') => `<div class="file"><span class="file-icon">PDF</span><div><p><strong>${name}</strong></p><p class="muted">${details}</p></div><button type="button" class="text-button" data-dialog="proof" style="margin-left:auto">Visualizar</button></div>`;
const upload = (label,proof=true) => `<div class="upload"><div class="icon" aria-hidden="true">↑</div><label>${label}<input type="file" ${proof?'accept="application/pdf,image/jpeg,image/png"':''} aria-label="${label}"></label><p>${proof?'PDF, JPEG ou PNG · até 10 MB':'Termo assinado e digitalizado · formatos a definir'}</p></div>`;
const checkbox = label => `<label class="check"><input type="checkbox"> <span>${label}</span></label>`;
const privacyChoices = () => `${notice('Textos finais em preparação','Os rótulos abaixo indicam escolhas separadas. O conteúdo aprovado será fornecido antes da abertura das inscrições.','neutral')}${['Li e aceito o regulamento do torneio.','Li as informações sobre o tratamento dos dados e a visibilidade de participação e resultados.','Declaro que as informações fornecidas são verdadeiras.','Li a declaração de ciência dos riscos da esgrima histórica.','Declaro possuir o equipamento obrigatório.','Li e aceito a declaração de aptidão física.','Li a política de cancelamento, reembolso e desclassificação.'].map(checkbox).join('')}<div class="divider"></div><h4>Uso de imagem · escolha independente</h4><label class="check"><input type="radio" name="image-choice" value="yes"> Autorizo o uso da minha imagem.</label><label class="check"><input type="radio" name="image-choice" value="no"> Não autorizo o uso da minha imagem.</label><p class="small muted">A recusa de imagem não substitui nem invalida os demais aceites. A lista limitada de participantes não tem opção de ocultar participação.</p>`;
function header(){const staff=current.role.startsWith('Staff') || (current.id==='WF-13'&&state==='staff');const guest=(['WF-01','WF-02','WF-03'].includes(current.id)&&state!=='member')||(current.id==='WF-14'&&state!=='directory');return `<header class="app-header"><a class="brand" href="#WF-01" aria-label="Karlbrüder, catálogo"><img src="${A}logos/logo_white_with_name.png" alt="Karlbrüder — esgrima histórica"></a><nav class="app-nav" aria-label="Aplicação"><a href="#WF-01" class="${['WF-01','WF-02'].includes(current.id)?'active':''}">Torneios</a>${!guest?'<a href="#WF-07">Minhas inscrições</a>':''}${staff?'<a class="active" href="#WF-09">Administração</a>':''}</nav><div class="account">${guest?button('Entrar','WF-03',''):staff?'<span class="avatar">EQ</span><span>Equipe</span>':'<span class="avatar">AE</span><span>Ana E.</span>'}</div></header>`;}
function catalog(){if(state==='empty'||state==='error')return `<div class="app-body">${intro('Circuito Karlbrüder','Torneios da guilda')}<div class="empty"><h3>${state==='empty'?'Nenhum torneio disponível':'Não foi possível carregar os torneios'}</h3><p class="muted">${state==='empty'?'Novos encontros aparecerão aqui quando estiverem disponíveis.':'Tente novamente. Nenhum dado de inscrição foi alterado.'}</p>${button('Voltar ao catálogo','WF-01')}</div></div>`;return `<div class="app-body">${intro('Esgrima histórica · Karlbrüder','Encontre seu próximo desafio.','Torneios, encontros e experiências para quem vive a esgrima.')}<div class="hero"><div>${tag('Inscrições abertas','wine')}<h2>Monomachia<br>Karlbrüder 2027</h2><p class="sub">Um encontro de técnica, respeito e espírito de guilda.</p><div class="hero-meta"><span>17 jan 2027</span><span>Longsword</span><span>Evento público</span></div><div class="actions">${button('Conhecer o torneio →','WF-02','','data-event="mono"')}</div></div><div class="event-mark"><img src="${A}monomachia/logo.svg" alt="Identidade Monomachia"></div></div><div class="panel-heading"><h3>Todos os torneios</h3><span class="small muted">${state==='member'?'3 eventos visíveis para membros':'2 eventos públicos · exemplo'}</span></div><div class="grid-2"><article class="event-card"><div class="cover wine"><strong>MONOMACHIA</strong><span class="small">2027</span></div><div class="content">${tag('Inscrições abertas','green')}<h3>Monomachia Karlbrüder</h3><p class="muted">Longsword · 17 de janeiro de 2027<br>Local a confirmar</p><footer><span>R$ 150,00 <small class="muted">/ exemplo</small></span>${button('Ver detalhes','WF-02','secondary','data-event="mono"')}</footer></div></article><article class="event-card"><div class="cover"><strong>Encontros da guilda</strong><span class="small">EXEMPLO</span></div><div class="content">${tag('Data a confirmar')}<h3>Encontro de esgrima da guilda</h3><p class="muted">Evento fictício para demonstrar o catálogo<br>Data, local e valor a confirmar</p><footer><span>Evento público</span>${button('Ver detalhes','WF-02','secondary','data-event="other" data-state="unknown"')}</footer></div></article>${state==='member'?`<article class="event-card"><div class="cover"><strong>Encontro interno</strong><span class="small">EXEMPLO</span></div><div class="content">${tag('Somente membros','blue')}<h3>Treino competitivo interno</h3><p class="muted">Acesso de membros da guilda e staff.</p>${button('Ver detalhes','','secondary','data-dialog="internal"')}</div></article>`:''}</div></div>`;}
function detail(){const full=state==='full',unknown=state==='unknown',closed=state==='closed';return `<div class="app-body"><a class="return-link" href="#WF-01">← Todos os torneios</a><div class="hero"><div><p class="overline">Karlbrüder apresenta</p><h2>${eventTitle()}</h2><div class="hero-meta"><span>${currentEvent==='mono'?'17 jan 2027':'Data a confirmar'}</span><span>Longsword</span><span>Público</span></div></div><div class="event-mark"><img src="${A}${currentEvent==='mono'?'monomachia/logo.svg':'logos/logo_white.png'}" alt="Marca do evento"></div></div>${full?notice('Vagas preenchidas. Inscrições continuam abertas.','Se o pagamento for aprovado sem uma vaga disponível, sua inscrição entrará na lista de espera. Inscrever-se e enviar comprovante não reservam vaga.'):closed?notice('Inscrições encerradas','Não é possível criar uma nova inscrição. Inscrições existentes continuam acessíveis.','neutral'):''}<div class="split"><section><div class="panel"><h3>Sobre o torneio</h3><p>Encontre as informações de participação, consulte o regulamento e acompanhe sua inscrição pela plataforma Karlbrüder.</p>${facts([['Modalidade','Longsword'],['Local','A confirmar'],['Programação','A confirmar'],['Participação','Inscrição individual e pessoal']])}</div><div class="panel"><h3>Antes de se inscrever</h3>${['Regulamento e elegibilidade','Equipamentos obrigatórios','Cancelamento e reembolso'].map(t=>`<details><summary>${t}</summary><p class="muted">Conteúdo do evento a ser configurado pela equipe. Este wireframe não define critérios, lista de equipamentos ou redação final.</p></details>`).join('')}<p class="small muted" style="margin-top:15px">Menores precisam de termo assinado pelo responsável, acompanhamento no evento e conferência presencial dos documentos de ambos.</p></div></section><aside><div class="panel"><span class="inline-label">INSCRIÇÃO</span><div class="amount">${unknown?'A confirmar':'R$ 150,00'}</div><p class="small muted">${unknown?'Valor ainda não informado':'Valor de exemplo · pagamento via Pix'}</p>${facts([['Período',unknown?'A confirmar':'01 nov – 10 jan · exemplo'],['Fuso','GMT-3'],['Disponibilidade',closed?'Encerrada':full?'Sem vaga confirmável':unknown?'A confirmar':'Inscrições abertas']])}<div class="actions">${closed||unknown?'<button class="button wide" disabled>Inscrições indisponíveis</button>':button(full?'Continuar com ciência da espera':'Inscrever-me','WF-03','wide')}</div><p class="small muted" style="margin-top:12px">Entre ou crie uma conta para se inscrever. Você só pode inscrever a si mesmo.</p></div></aside></div></div>`;}
function auth(){const signup=state==='signup',recover=state==='recover',reset=state==='reset',verify=state==='verify';return `<div class="auth-layout"><section class="auth-story"><p class="overline">Sua próxima experiência</p><h2>Da primeira inscrição<br>ao próximo encontro.</h2><p>Uma conta para acompanhar seus torneios na Karlbrüder.</p><hr class="divider"><p class="small">Você está continuando a inscrição em<br><strong>${eventTitle()}</strong></p></section><section class="auth-form">${intro('Sua conta',verify?'Confira seu e-mail':recover?'Recuperar acesso':reset?'Escolha uma nova senha':signup?'Faça parte.':'Boas-vindas de volta.')} ${state==='expired'?notice('Sua sessão expirou','Entre novamente para continuar no torneio selecionado.','info'):''}${state==='unavailable'?notice('Serviço temporariamente indisponível','Não foi possível conectar ao serviço de acesso. Tente novamente em instantes.','error'):''}${verify?`${notice('Enviamos as instruções de verificação','Consulte sua caixa de entrada e siga o link para ativar o acesso.','success')}<p class="muted">Após verificar seu e-mail, entre para continuar.</p>${button('Voltar para entrar','WF-03','wide')}`:reset?`${field('Nova senha','','type="password" autocomplete="new-password"')}${field('Repita a nova senha','','type="password" autocomplete="new-password"')}${button('Atualizar senha','WF-03','wide')}`:`${!recover?button('Continuar com Google','WF-04','secondary wide')+'<div class="or">ou use seu e-mail</div>':''}${field('E-mail','','type="email" placeholder="voce@exemplo.com" autocomplete="email"')}${!recover?field('Senha','','type="password" autocomplete="current-password"'):''}${button(recover?'Enviar link de recuperação':signup?'Criar minha conta':'Entrar',recover?'':signup?'WF-03':'WF-04','wide',recover?'data-dialog="recovery"':signup?'data-state="verify"':'')}${!signup&&!recover?'<div class="actions"><button class="text-button" data-go="WF-03" data-state="recover">Esqueci minha senha</button></div>':''}<hr class="divider"><p class="small">${signup||recover?'Já tem acesso?':'Ainda não tem conta?'} <button class="text-button" data-go="WF-03" data-state="${signup||recover?'login':'signup'}">${signup||recover?'Entrar':'Criar conta'}</button></p>`}</section></div>`;}
function identityFields(edit=false){return `<div class="form-grid">${field('Nome completo *','Ana Exemplo','autocomplete="name"')}${field('Nome social (opcional)','','placeholder="Como prefere ser chamada"')}${field('E-mail da inscrição *','ana@example.com',edit?'type="email"':'type="email" readonly')}${field('Telefone *','','type="tel" placeholder="DDD + número"')}${selectField('Documento *',['CPF','Passaporte'])}${field('Número do documento *','','placeholder="Informe o documento"')}${field('Data de nascimento *','','type="date"')}${field('País *','Brasil')}${field('Cidade *','')}${field('Estado / província (opcional)','')}</div>`;}
function sportFields(){return `<div class="form-grid">${field('Tempo de prática em HEMA','','placeholder="Duração em anos / meses"')}${field('Ano de início em HEMA','','inputmode="numeric" placeholder="Ou informe o ano de início"')}<p class="small muted full">Informe tempo de prática, ano de início ou ambos.</p>${field('Torneios anteriores *','0','type="number" min="0"')}${field('Escola / equipe (opcional)','')}${field('Instrutor responsável (opcional)','')}${field('Referência HEMA Ratings (opcional)','')}${field('Lateralidade (opcional)','','placeholder="Ex.: destra"')}${field('Categoria / caso especial (opcional)','','placeholder="Sujeito à avaliação da equipe"')}</div>`;}
function emergency(){return `<div class="form-grid">${field('Contato de emergência *','','placeholder="Nome completo"')}${field('Telefone de emergência *','','type="tel"')}</div>`;}
function registration(){let n='';if(state==='full')n=notice('O torneio está lotado','O envio da inscrição não coloca você na lista de espera. Após pagamento aprovado, a equipe confirma se houver vaga ou registra a espera.');if(state==='invalid')n=notice('Revise os campos antes de continuar','Informe seu documento, contato de emergência e os aceites obrigatórios. Nenhuma inscrição foi criada.','error');if(state==='duplicate')n=notice('Já existe uma inscrição ativa','Encontramos uma inscrição para esta conta, e-mail ou documento neste torneio. Acesse Minhas inscrições para acompanhá-la.','error');if(state==='closed')n=notice('As inscrições foram encerradas','O período terminou ou a equipe encerrou novas inscrições. Seus dados não foram enviados.','error');return `<div class="app-body"><a href="#WF-02" class="return-link">← ${eventTitle()}</a>${intro('Inscrição pessoal','Seu próximo passo começa aqui.','Campos com * são obrigatórios. Você está se inscrevendo para si.')}<ol class="stepper"><li class="active"><span>1</span> Inscrição</li><li><span>2</span> Pix e comprovante</li><li><span>3</span> Acompanhamento</li></ol>${n}<div class="split"><section><div class="panel"><h3><span class="form-section-number">01</span> Dados pessoais</h3>${identityFields()}<p class="small muted">O e-mail corresponde à sua conta. Seus dados privados não aparecem na lista de participantes.</p></div><div class="panel"><h3><span class="form-section-number">02</span> Sua experiência</h3>${sportFields()}</div><div class="panel"><h3><span class="form-section-number">03</span> Segurança e participação</h3>${emergency()}${state==='minor'?notice('Participação de menor de idade','Envie o termo assinado pelo responsável. No evento, você deverá estar acompanhado e ambos apresentarão seus documentos para conferência.','info')+upload('Termo de responsabilidade assinado',false):''}${privacyChoices()}</div></section><aside><div class="panel tinted"><h3>${eventTitle()}</h3>${facts([['Modalidade','Longsword'],['Data',currentEvent==='mono'?'17 jan 2027':'A confirmar'],['Valor','R$ 150,00 · exemplo']])}<p class="small muted" style="margin-top:15px">Sua vaga só é confirmada após a análise da equipe, conforme a disponibilidade.</p>${button('Enviar minha inscrição','WF-05','wide',state==='closed'?'disabled':'')}<p class="small muted" style="margin-top:13px">Não há salvamento automático de inscrição incompleta nesta proposta.</p></div></aside></div></div>`;}
function payment(){const replacing=state==='replace';const resubmitting=replacing||state==='rejected';return `<div class="app-body"><a href="#WF-07" class="return-link">← Minhas inscrições</a>${intro('Inscrição MONO2027001 · exemplo',replacing?'Substituir comprovante.':state==='rejected'?'Precisamos de outro comprovante.':'Inscrição recebida. Agora, o Pix.',eventTitle(),tag(replacing?'Nova evidência':state==='rejected'?'Reenvio solicitado':'Aguardando pagamento','amber'))}${replacing?notice('Envie uma nova evidência','A equipe analisará o novo arquivo. Substituir o comprovante não é realizar outro pagamento nem obter aprovação automática.','info'):state==='rejected'?notice('Comprovante recusado','Motivo de exemplo: não foi possível identificar o valor e o favorecido. Envie um novo arquivo. Você também recebe uma notificação.','error'):state==='fileerror'?notice('Este arquivo não foi aceito','Escolha PDF, JPEG ou PNG de até 10 MB. Nenhum novo comprovante foi armazenado.','error'):state==='late'?notice('O prazo de pagamento passou','A equipe avaliará manualmente a transferência. O prazo vencido não confirma nem cancela a inscrição automaticamente.'):notice('A inscrição ainda não garante vaga','Faça o pagamento via Pix e envie o comprovante. A equipe fará a conferência antes da confirmação.','info')}<div class="split"><section><div class="panel"><h3>1. ${resubmitting?'Confira o pagamento realizado':'Faça o Pix fora da plataforma'}</h3>${resubmitting?'<p class="small">O reenvio de um comprovante, por si só, não exige outra transferência. Confira os dados antes de enviar a evidência.</p>':''}<div class="amount">R$ 150,00</div><p class="small muted">Valor fictício para este cenário</p>${facts([['Favorecido','[Conta recebedora configurada]'],['Chave Pix','[Chave a ser configurada]'],['Prazo','12 jan 2027 · exemplo']])}<p class="small muted" style="margin-top:16px">Confira os dados do favorecido no aplicativo do seu banco. Este wireframe não contém uma chave Pix utilizável.</p></div><div class="panel"><h3>2. Envie seu comprovante</h3>${resubmitting?file('comprovante-anterior.pdf',replacing?'Último envio · exemplo':'Último envio · recusado'):''}${upload('Selecionar comprovante')}${replacing?button('Enviar novo comprovante','','wide','data-dialog="replacement"'):button('Enviar comprovante','WF-06','wide','data-state="review"')}<p class="small muted" style="margin-top:13px">Enviar arquivo não realiza pagamento nem reserva vaga.</p></div></section><aside><div class="panel"><h3>Sua inscrição</h3>${facts([['Participante','Ana Exemplo'],['Número','MONO2027001'],['Evento',eventTitle()]])}<ol class="timeline"><li class="done">Inscrição recebida<small>Dados enviados para este torneio</small></li><li class="current">Enviar comprovante<small>Aguardando seu envio</small></li><li>Análise da equipe<small>Confirmação depende de elegibilidade e capacidade</small></li></ol></div></aside></div></div>`;}
function status(){const cfg=state==='confirmed'?['Inscrição confirmada.','Sua participação está confirmada. Consulte o regulamento e prepare seu equipamento.','Confirmada','green']:state==='waitlist'?['Pagamento aprovado. Aguardando vaga.','Você está na lista de espera, sem vaga confirmada. A equipe decide quem selecionar quando houver disponibilidade.','Lista de espera','amber']:['Recebemos seu comprovante.','A equipe vai conferir seu pagamento. Até a confirmação, nenhuma vaga está reservada.','Pagamento em análise','blue'];return `<div class="app-body"><a class="return-link" href="#WF-07">← Minhas inscrições</a>${intro('MONO2027001 · exemplo',cfg[0],eventTitle(),tag(cfg[2],cfg[3]))}<div class="split"><section><div class="panel"><div class="state-title"><span class="state-icon" aria-hidden="true">${state==='confirmed'?'✓':'◷'}</span><h3 class="no-margin">${cfg[2]}</h3></div><p>${cfg[1]}</p>${state==='waitlist'?notice('Não é necessário pagar novamente','Não há promoção automática, posição de prioridade ou prazo de chamada. A entrada na espera é comunicada por e-mail.'):''}${state==='confirmed'?notice('Se você for menor de idade','Leve o responsável. No evento, a equipe verificará os documentos de ambos; o termo enviado não substitui essa conferência.','info'):''}${facts([['Participante','Ana Exemplo'],['Data do evento','17 jan 2027'],['Local','A confirmar'],['Pagamento',state==='review'?'Em análise':'Aprovado'],['Vaga',state==='confirmed'?'Confirmada':'Não reservada']])}<div class="actions">${button('Ver meus dados','WF-08','secondary')}${button('Ver detalhes do torneio','WF-02','secondary')}</div></div><div class="panel"><h3>Último comprovante enviado</h3>${file()}${button('Substituir comprovante','WF-05','secondary','data-state="replace"')}<p class="small muted" style="margin-top:12px">A substituição gera uma nova evidência para análise. A equipe mantém o histórico de envios.</p></div></section><aside><div class="panel"><h3>Acompanhamento</h3><ol class="timeline"><li class="done">Inscrição recebida<small>Número gerado</small></li><li class="done">Comprovante enviado<small>Arquivo recebido pela plataforma</small></li><li class="${state==='review'?'current':'done'}">${state==='review'?'Pagamento em análise':'Pagamento aprovado'}</li><li class="${state==='confirmed'?'done':state==='waitlist'?'current':''}">${state==='confirmed'?'Participação confirmada':state==='waitlist'?'Aguardando seleção da equipe':'Aguardar decisão da equipe'}</li></ol></div></aside></div></div>`;}
function myRegistrations(){return `<div class="app-body">${intro('Área pessoal','Minhas inscrições','Acompanhe seus pagamentos e sua participação.',button('Explorar torneios','WF-01','secondary'))}${state==='empty'?`<div class="empty"><h3>Seu próximo torneio começa aqui.</h3><p class="muted">Você ainda não tem inscrições. Explore os eventos públicos da guilda.</p>${button('Ver torneios','WF-01')}</div>`:`<div class="panel"><div class="panel-heading"><div><p class="overline">MONO2027001 · exemplo</p><h3>${eventTitle()}</h3></div>${tag('Pagamento em análise','blue')}</div><p class="muted">Longsword · 17 jan 2027 · Ana Exemplo</p>${notice('Comprovante recebido','Você ainda não tem vaga reservada. Acompanhe a decisão da equipe.','info')}<div class="actions">${button('Acompanhar inscrição','WF-06')}${button('Editar meus dados','WF-08','secondary')}</div></div><p class="small muted">Só você e a equipe autorizada acessam os detalhes privados desta inscrição.</p>`}</div>`;}
function editRegistration(){return `<div class="app-body"><a class="return-link" href="#WF-06">← Acompanhar inscrição</a>${intro('MONO2027001 · exemplo','Meus dados da inscrição','Correções mantêm o mesmo titular, torneio e número.')} ${state==='conflict'?notice('Não foi possível salvar','O documento ou e-mail conflita com uma inscrição ativa deste torneio. Nenhum dado foi alterado.','error'):''}<div class="panel"><h3>Dados pessoais</h3>${identityFields(true)}<h3>Experiência e equipe</h3>${sportFields()}<h3>Contato de emergência</h3>${emergency()}<details><summary>Rever minhas declarações e autorizações</summary>${privacyChoices()}</details><div class="actions">${button('Salvar alterações','','','data-dialog="saved"')}${button('Voltar','WF-06','secondary')}</div></div></div>`;}
function staffQueue(){return `<div class="app-body">${intro('Equipe Karlbrüder','Análise de pagamentos','Todos os torneios · acesso administrativo')}<div class="stats"><div><div class="metric">8</div><p>Comprovantes pendentes</p></div><div><div class="metric">56 / 64</div><p>Confirmados · Monomachia</p></div><div><div class="metric">3</div><p>Em espera · exemplo</p></div></div><div class="filters"><input aria-label="Buscar inscrição" placeholder="Nome, equipe, cidade ou inscrição"><select aria-label="Torneio"><option>Todos os torneios</option><option>Monomachia 2027</option></select><select aria-label="Situação"><option>Pagamento em análise</option><option>Aguardando pagamento</option><option>Confirmados</option><option>Em espera</option></select></div>${state==='empty'?'<div class="empty"><h3>Nenhum comprovante pendente.</h3><p class="muted">Novos envios aparecerão nesta fila.</p></div>':`<div class="panel"><div class="panel-heading"><h3>Comprovantes para conferir</h3><span class="small muted">Amostra fictícia</span></div><div class="table-wrap"><table><thead><tr><th>Participante / inscrição</th><th>Torneio</th><th>Pagamento</th><th>Ação</th></tr></thead><tbody>${['Ana Exemplo','Bruno Exemplo','Carla Exemplo'].map((n,i)=>`<tr><td><p><strong>${n}</strong></p><small>MONO202700${i+1}</small></td><td>Monomachia 2027</td><td>${tag('Em análise','blue')}</td><td>${button('Revisar','WF-10','secondary')}</td></tr>`).join('')}</tbody></table></div></div>`}<p class="small muted">A abertura de uma análise não reserva vagas. As decisões são registradas com responsável e horário.</p></div>`;}
function staffReview(){const full=['full','race'].includes(state);return `<div class="app-body"><a class="return-link" href="#WF-09">← Fila de análise</a>${intro('Equipe · MONO2027001','Conferir pagamento e participação.','Ana Exemplo · Monomachia Karlbrüder 2027',tag('Em análise','blue'))}${state==='race'?notice('A disponibilidade mudou','Outra confirmação ocupou a última vaga. A decisão deverá considerar a lotação atual; nenhum participante pode ser confirmado acima do limite.','info'):''}${state==='late'?notice('Transferência após o prazo','Aceitar segue a regra normal de vagas. Para recusar participação após dinheiro recebido, use cancelamento com reembolso; recusar comprovante é uma ação diferente.'):''}<div class="split"><section><div class="panel"><h3>Comprovante mais recente</h3><div class="proof-sheet"><div class="proof-paper"><p class="overline">DOCUMENTO FICTÍCIO</p><h4>Comprovante de Pix</h4><div class="metric">R$ 150,00</div><hr><p>Ana Exemplo → conta da guilda</p><p>Sem dados bancários reais</p><p class="muted">Ilustração do espaço de conferência</p></div></div>${file('comprovante-atual.pdf','Versão 2 · exemplo')}<details><summary>Histórico de comprovantes · 2 versões</summary>${file('comprovante-anterior.pdf','Versão 1 · recusada') }<p class="small muted">Histórico restrito à equipe.</p></details></div><div class="panel"><h3>Dados e elegibilidade</h3>${facts([['Nome','Ana Exemplo'],['Equipe','Equipe de exemplo'],['Experiência HEMA','2 anos · exemplo'],['Torneios anteriores','0'],['Documento','[Acesso privado de staff]']])}${state==='minor'?notice('Participante menor de idade','Conferir termo assinado antes da decisão. No evento, verificar documentos do participante e responsável e o acompanhamento.','info')+file('termo-responsabilidade.pdf','Documento privado · exemplo'):''}<details><summary>Dados restritos e nota de segurança</summary>${textarea('Nota interna da equipe','')}<p class="small muted">Somente staff. Não aparece ao participante ou em exportações gerais.</p></details></div></section><aside><div class="panel"><h3>Decisão da equipe</h3>${facts([['Valor configurado','R$ 150,00 · exemplo'],['Participação confirmada',full?'64 / 64':'56 / 64'],['Resultado da aprovação',full?'Lista de espera':'Confirmar, se elegível']])}${full?notice('Sem vaga disponível','Aprovar o pagamento inclui na espera e notifica por e-mail. Não confirma vaga.'):''}${checkbox('Conferi o recebimento e o valor do pagamento.')}${checkbox('Conferi os requisitos de participação e a documentação aplicável.')}${state==='reject'?`${textarea('Motivo da recusa *','Não foi possível identificar o favorecido no arquivo.')}<p class="small muted">O motivo será mostrado ao participante e enviado na notificação.</p>${button('Recusar e solicitar novo envio','','wide danger','data-dialog="rejected"')}`:`${button(full?'Aprovar pagamento → lista de espera':'Aprovar pagamento e confirmar','','wide','data-dialog="approved"')}${button('Recusar comprovante','WF-10','secondary wide','data-state="reject" style="margin-top:9px"')}`}${state==='late'?`<div class="actions">${button('Cancelar e encaminhar reembolso','WF-13','secondary','data-state="staff"')}</div>`:''}<p class="small muted" style="margin-top:13px">A decisão registra responsável e horário. A capacidade é conferida novamente ao confirmar.</p></div></aside></div></div>`;}
function waitlist(){return `<div class="app-body">${intro('Operação · Monomachia 2027','Participantes em espera','Pagamentos já aprovados. A seleção é uma decisão da equipe.')}<div class="stats"><div><div class="metric">${state==='seat'?'63':'64'} / 64</div><p>Participantes confirmados</p></div><div><div class="metric">3</div><p>Pagamentos aprovados em espera</p></div><div><div class="metric">${state==='seat'?'1':'0'}</div><p>Vagas disponíveis</p></div></div>${notice('Nenhuma promoção automática','O surgimento de uma vaga não muda nenhuma inscrição. Selecione explicitamente quem confirmar.','info')}<div class="panel"><div class="table-wrap"><table><thead><tr><th>Participante</th><th>Inscrição</th><th>Pagamento</th><th>Ação</th></tr></thead><tbody>${['Ana Exemplo','Bruno Exemplo','Carla Exemplo'].map((n,i)=>`<tr><td>${n}</td><td>MONO202700${i+1}</td><td>${tag('Aprovado','green')}</td><td>${button('Confirmar participação','','secondary',state==='full'?'disabled':'data-dialog="waitlist-confirm"')}</td></tr>`).join('')}</tbody></table></div></div><p class="small muted">A ordem ilustrativa da tabela não representa prioridade. A confirmação ainda verifica elegibilidade e capacidade.</p></div>`;}
function eventSettings(){return `<div class="app-body">${intro('Administração · extensão','Informações do torneio','Edições globais de staff, com preservação de histórico.')}${state==='capacityerror'?notice('Capacidade não pode ser menor que 56','Existem 56 participantes confirmados neste cenário. A alteração foi recusada sem cancelar inscrições.','error'):''}<div class="panel"><div class="form-grid">${field('Nome','Monomachia Karlbrüder 2027')}${field('Modalidade','Longsword')}${field('Início do evento','2027-01-17','type="date"')}${field('Término do evento','2027-01-17','type="date"')}${field('Abertura das inscrições','2026-11-01','type="date"')}${field('Encerramento das inscrições','2027-01-10','type="date"')}${field('Prazo de pagamento','2027-01-12','type="date"')}${field('Valor em BRL','150.00','type="number" min="0"')}${field('Capacidade total',state==='capacityerror'?'50':'64','type="number" min="0"')}${field('Local','','placeholder="A confirmar"')}</div><p class="small muted">Valores são exemplos. Capacidade em branco é ilimitada. Janela de inscrição inclui ambos os dias em GMT-3.</p>${checkbox('Torneio interno — somente membros da guilda e staff')}${textarea('Programação')}${textarea('Regulamento / link')}${textarea('Equipamentos obrigatórios')}${textarea('Política de cancelamento / link')}<div class="actions">${button('Salvar alterações','','','data-dialog="event-save"')}${button('Encerrar novas inscrições','','danger','data-dialog="close-registration"')}</div><p class="small muted" style="margin-top:12px">Encerrar inscrições não cancela inscrições existentes. Lotação, por si só, não encerra o formulário.</p></div></div>`;}
function refund(){const pending=state==='pending',done=state==='refunded',staff=state==='staff',unpaid=state==='unpaid';return `<div class="app-body">${intro(staff?'Equipe · reembolso':'Minha inscrição',done?'Participação cancelada. Valor devolvido.':pending?'Participação cancelada. Reembolso pendente.':staff?'Registrar reembolso realizado.':'Cancelar participação',eventTitle())}<div class="split"><div class="panel">${notice(pending||done?'Sua participação está cancelada':'O cancelamento encerra a participação',pending?'Sua vaga já foi liberada. O reembolso não reativa esta inscrição.':done?'A equipe registrou a devolução. A confirmação é enviada ao seu e-mail atual.':'Qualquer vaga ocupada será liberada imediatamente, sem esperar o reembolso.',done?'success':'info')}${facts([['Inscrição','MONO2027001'],['Participação',pending||done||staff?'Cancelada':'Será cancelada'],['Valor recebido',unpaid?'Sem pagamento':'R$ 150,00 · exemplo'],['Reembolso',unpaid?'Não se aplica':done?'Concluído':pending||staff?'Aguardando reembolso':'Integral do valor recebido']])}${!unpaid?'<p class="small muted" style="margin-top:15px">Prazo: até 10 dias úteis após o cancelamento pago. A devolução é feita pela guilda fora da plataforma.</p>':''}${staff?`${field('Data da devolução','','type="date"')}${field('Valor efetivamente devolvido','150.00','type="number"')}${button('Registrar devolução concluída','WF-13','','data-state="refunded"')}`:pending||done?`${button('Voltar ao torneio','WF-02','secondary')}<p class="small muted" style="margin-top:13px">Uma nova inscrição pode ser criada, respeitando as regras de abertura. O reembolso anterior não impede nova inscrição.</p>`:`<div class="actions">${button('Confirmar cancelamento','WF-13','danger',unpaid?'data-dialog="unpaid-cancel"':'data-state="pending"')}${button('Manter participação','WF-06','secondary','data-state="confirmed"')}</div>`}</div><aside class="panel tinted"><h3>Participação e dinheiro</h3><p>Cancelar e receber de volta são etapas diferentes. O aplicativo não realiza uma transferência de reembolso.</p></aside></div></div>`;}
function results(){return `<div class="app-body">${intro('Monomachia Karlbrüder 2027',state==='directory'?'Participantes':'Resultados',state==='directory'?'Projeção limitada · contexto autenticado':'Consulta vinculada ao torneio selecionado')}${state==='restricted'?`<div class="empty"><h3>Acesso restrito.</h3><p class="muted">Não é possível acessar este conteúdo com a conta atual. Dados do evento interno não são exibidos.</p>${button('Voltar aos torneios','WF-01')}</div>`:state==='directory'?`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Nome de exibição</th><th>Escola / equipe</th><th>Cidade / país</th><th>Confirmação</th></tr></thead><tbody><tr><td>Ana Exemplo</td><td>Equipe de exemplo</td><td>Cidade de exemplo / Brasil</td><td>${tag('Confirmada','green')}</td></tr></tbody></table></div></div>`:state==='published'?`<div class="panel"><h3>Resultados publicados</h3><div class="skeleton">Área reservada ao formato aprovado de resultados.<br>Conteúdo e representação dependem de RES-Q1–Q4.<br>Não há ranking, pontuação ou chave presumidos.</div><p class="small muted" style="margin-top:18px">Apenas resultados públicos de eventos não internos podem ser consultados por visitantes.</p></div>`:`<div class="empty"><h3>Resultados ainda não disponíveis.</h3><p class="muted">Quando houver resultados publicados para este evento, você poderá consultá-los aqui.</p>${button('Ver detalhes do torneio','WF-02','secondary')}</div>`}</div>`;}
function membership(){return `<div class="app-body">${intro('Área do membro · conceito futuro','Minha associação','Acompanhamento de vínculo e mensalidades, separado dos torneios.')}<div class="grid-2"><div class="panel"><h3>Meu vínculo com a guilda</h3><div class="skeleton">[Informações de vínculo autorizadas]<br>Admissão, saída e vocabulário de situação a definir — MEM-Q1 e MEM-Q2.</div></div><div class="panel"><h3>Minhas mensalidades</h3><div class="skeleton">[Informações de períodos e valores]<br>Política de cobrança, isenções e descontos a definir — MEM-Q3 e MEM-Q4.</div></div></div>${notice('Cada pagamento tem seu propósito','Pagar a inscrição de um torneio não quita mensalidades da associação. Nem todo membro é pagante.','info')}<div class="panel"><h3>Registro de pagamentos</h3><div class="skeleton">Forma de registro a definir — MEM-Q5.<br>Este conceito não estabelece cobrança recorrente, gateway ou prazo de vencimento.</div></div></div>`;}
function inventory(){return `<div class="app-body">${intro('Administração da guilda · futuro','Equipamentos compartilhados','Inventário independente dos torneios.',state==='list'?button('Adicionar equipamento','WF-16','','data-state="edit"'):'')}${state==='edit'?`<div class="panel"><div class="form-grid">${field('Equipamento','Máscara de esgrima')}${field('Tipo','Proteção')}${field('Quantidade','8','type="number" min="0"')}${field('Condição','Boa','placeholder="Descrição da condição"')}</div><div class="actions">${button('Salvar registro','WF-16')}${button('Retirar do inventário','','danger','data-dialog="retire"')}${button('Voltar','WF-16','secondary')}</div></div>`:`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Equipamento</th><th>Tipo</th><th>Quantidade</th><th>Condição</th><th></th></tr></thead><tbody>${[['Máscara de esgrima','Proteção','8','Boa'],['Espada de treino','Longsword','4','Nova'],['Broquel','Escudo','3','Desgastada']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}<td>${button('Editar','WF-16','secondary','data-state="edit"')}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:18px">Dados fictícios. Condições são descrições ilustrativas, não uma lista fechada.</p></div>`}<p class="small muted">Área exclusiva de staff. O uso físico por membros não concede acesso a estes registros.</p></div>`;}
const dialogs={
 replacement:['Nova evidência recebida · simulação','O novo arquivo requer análise. O participante verá somente esta versão; a equipe manterá o histórico. Este diálogo não confirma nem cancela a participação.'],
 proof:['Documento de demonstração','Este espaço representa a visualização privada do arquivo autorizado. Nenhum documento real foi carregado. O participante só acessa o comprovante mais recente; staff também acessa versões anteriores.'],
 internal:['Evento interno · cenário de membro','O usuário membro pode consultar e se inscrever em eventos internos, respeitando a elegibilidade. Este cartão não aparece no cenário de visitante.'],
 recovery:['Recuperação de acesso','Prévia do retorno: se a conta puder receber a recuperação, consulte o e-mail e siga as instruções. Nenhuma mensagem foi enviada pelo wireframe. Use o seletor de estado para visualizar a definição de nova senha.'],
 saved:['Alterações recebidas · simulação','Na aplicação, o backend validará os campos e preservará os aceites anteriores. Este wireframe não grava alterações.'],
 rejected:['Nova evidência solicitada · simulação','A equipe informa o motivo da recusa, notifica o participante e permite outro envio. Recusar o comprovante não cancela a participação nem ocupa vaga.'],
 approved:['Decisão de pagamento · simulação','O backend revalida elegibilidade, documentação e capacidade ao aprovar. Havendo vaga, confirma; sem vaga, registra a espera e dispara a notificação. Não existe overbooking.'],
 'waitlist-confirm':['Confirmar participante selecionado','O pagamento já está aprovado. A confirmação depende de elegibilidade e vaga disponível no momento da decisão. O protótipo não altera registros.'],
 'event-save':['Salvar informações · simulação','Mudanças em datas, programação, local, regulamento, equipamentos ou cancelamento notificam os inscritos. Versões anteriores de aceites permanecem preservadas.'],
 'close-registration':['Encerrar novas inscrições','A equipe pode encerrar novas inscrições sem cancelar participantes existentes ou alterar a capacidade. Esta ação será confirmada explicitamente na aplicação.'],
 'unpaid-cancel':['Participação cancelada · simulação','Sem pagamento recebido, não há reembolso devido. A inscrição permanece cancelada e uma nova inscrição pode ser criada se o evento aceitar inscrições.'],
 retire:['Retirar registro do inventário','Retirada do registro é permitida. A escolha técnica entre arquivamento e exclusão será definida na implementação, sem acrescentar empréstimos ou histórico de manutenção.']
};
const picker=document.getElementById('screen-picker'),statePicker=document.getElementById('state-picker');
for(const phase of [...new Set(screens.map(s=>s.phase))]){const group=document.createElement('optgroup');group.label=phase;screens.filter(s=>s.phase===phase).forEach(s=>{const o=document.createElement('option');o.value=s.id;o.textContent=s.title;group.append(o)});picker.append(group)}
function render(){picker.value=current.id;statePicker.innerHTML=Object.entries(current.states).map(([key,label])=>`<option value="${key}">${label}</option>`).join('');statePicker.value=state;document.getElementById('screen-meta').textContent=`${current.id} · ${current.phase} · ${current.role}`;document.getElementById('prototype').innerHTML=`${header()}${current.phase!=='Primeira entrega'?`<div class="future-note">CONCEITO DE REVISÃO · ${current.phase.toUpperCase()} · NÃO INCLUIR NA PRIMEIRA ENTREGA</div>`:''}${current.render()}<footer class="app-footer"><span>Karlbrüder · esgrima histórica</span><span>app.karlbruder.com</span></footer>`;document.getElementById('spec-notes').innerHTML=`<div><h2>LEITURA DA TELA</h2><p>${current.title}</p><p>${current.role} · ${current.states[state]}</p><p>${current.rules.map(r=>`<span class="rule-tag">${r}</span>`).join('')}</p></div><div><h2>CONTRATOS DE ORIGEM</h2>${current.refs.map(r=>`<a href="../../${r}">${r} ↗</a>`).join('')}</div><div><h2>O QUE PRESERVAR</h2><ul>${current.notes.map(n=>`<li>${n}</li>`).join('')}</ul></div><div><h2>PROPOSTA VISUAL</h2><p>Layout, navegação e microcopy são propostas. Cenários e valores fictícios não alteram regras do produto.</p><p>Use os seletores acima para comparar estados e a largura de celular.</p></div>`;}
function navigate(id,variant,scroll=true){current=screens.find(s=>s.id===id)||screens[0];state=variant in current.states?variant:Object.keys(current.states)[0];history.replaceState(null,'',`#${current.id}/${state}`);render();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
picker.addEventListener('change',()=>navigate(picker.value));statePicker.addEventListener('change',()=>navigate(current.id,statePicker.value,false));
document.getElementById('desktop').onclick=()=>{document.body.classList.remove('mobile');document.getElementById('desktop').setAttribute('aria-pressed','true');document.getElementById('mobile').setAttribute('aria-pressed','false')};document.getElementById('mobile').onclick=()=>{document.body.classList.add('mobile');document.getElementById('desktop').setAttribute('aria-pressed','false');document.getElementById('mobile').setAttribute('aria-pressed','true')};
document.getElementById('annotations').onclick=e=>{document.body.classList.toggle('no-notes');e.currentTarget.setAttribute('aria-pressed',String(!document.body.classList.contains('no-notes')))};
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-dialog],a[href^="#WF-"]');if(!b)return;e.preventDefault();if(b.dataset.event)currentEvent=b.dataset.event;if(b.dataset.dialog){const data=dialogs[b.dataset.dialog];if(data){document.getElementById('dialog-content').innerHTML=`<h3>${data[0]}</h3><p>${data[1]}</p>`;document.getElementById('dialog').showModal()}return;}const id=b.dataset.go||b.getAttribute('href').slice(1);if(id)navigate(id,b.dataset.state)});
document.getElementById('close-dialog').onclick=()=>document.getElementById('dialog').close();
document.addEventListener('submit',e=>e.preventDefault());
const initial=location.hash.slice(1).split('/');navigate(initial[0]||'WF-01',initial[1],false);
